def countFactorialChains(n, length):
    fact = [1, 1, 2, 6, 24, 120, 720, 5040, 40320, 362880]

    def f(x):
        s = 0
        while x:
            x, d = divmod(x, 10)
            s += fact[d]
        return s

    memo = {}
    count = 0
    for x in range(1, n + 1):
        if x not in memo:
            path = []
            pos = {}
            u = x
            while u not in memo and u not in pos:
                pos[u] = len(path)
                path.append(u)
                u = f(u)
            if u in pos:
                j = pos[u]
                c = len(path) - j
                for i in range(j, len(path)):
                    memo[path[i]] = c
                end = j
            else:
                end = len(path)
            for i in range(end - 1, -1, -1):
                nxt_val = f(path[i])
                memo[path[i]] = memo[nxt_val] + 1
        if memo[x] == length:
            count += 1
    return count
